{
  "primary_meaning": "the good news of salvation through the life, death, and resurrection of Jesus Christ",
  "primary_basis": [
    "Mark 1:1",
    "Mark 1:14-15",
    "Romans 1:16",
    "1 Corinthians 15:1-4",
    "Matthew 4:23",
    "Isaiah 52:7 (as background)"
  ],
  "alternatives": [
    {
      "meaning": "the four canonical New Testament books (Matthew, Mark, Luke, John) that narrate the life and ministry of Jesus",
      "basis": [
        "early church usage and titles of the books",
        "Irenaeus and subsequent patristic tradition"
      ],
      "prominence": "common"
    },
    {
      "meaning": "the announcement of the kingdom of God / reign of God as present and future reality",
      "basis": [
        "Mark 1:14-15",
        "Matthew 4:23",
        "Luke 4:18-19 / Isaiah 61:1"
      ],
      "prominence": "common"
    },
    {
      "meaning": "a literary genre of ancient biography focused on Jesus",
      "basis": [
        "modern biblical scholarship on genre",
        "comparisons with Greco-Roman bioi"
      ],
      "prominence": "minority"
    }
  ],
  "has_settled_consensus": true,
  "confidence": "high",
  "notes": "Across historic Christian teaching the Greek euangelion is uniformly rendered and understood as 'good news.' The precise content of that news (kingdom emphasis vs. cross-resurrection emphasis) receives different accents, yet these are complementary rather than contradictory readings of the same core term. No significant symbolic or allegorical redefinition exists outside this consensus."
}
